import snannsumkbn = require( './index' );


// TESTS //

// The function returns a Float32Array...
{
	const x = new Float32Array( 10 );
	const sum = new Float32Array( 1 );
	const count = new Int32Array( 1 );

	snannsumkbn( x.length, x, 1, sum, count ); // $ExpectType Float32Array
}

// The compiler throws an error if the function is provided a first argument which is not a number...
{
	const x = new Float32Array( 10 );
	const sum = new Float32Array( 1 );
	const count = new Int32Array( 1 );

	snannsumkbn( '10', x, 1, sum, count ); // $ExpectError
	snannsumkbn( true, x, 1, sum, count ); // $ExpectError
	snannsumkbn( false, x, 1, sum, count ); // $ExpectError
	snannsumkbn( null, x, 1, sum, count ); // $ExpectError
	snannsumkbn( undefined, x, 1, sum, count ); // $ExpectError
	snannsumkbn( [], x, 1, sum, count ); // $ExpectError
	snannsumkbn( {}, x, 1, sum, count ); // $ExpectError
	snannsumkbn( ( x: number ): number => x, x, 1, sum, count ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a Float32Array...
{
	const x = new Float32Array( 10 );
	const sum = new Float32Array( 1 );
	const count = new Int32Array( 1 );

	snannsumkbn( x.length, 10, 1, sum, count ); // $ExpectError
	snannsumkbn( x.length, '10', 1, sum, count ); // $ExpectError
	snannsumkbn( x.length, true, 1, sum, count ); // $ExpectError
	snannsumkbn( x.length, false, 1, sum, count ); // $ExpectError
	snannsumkbn( x.length, null, 1, sum, count ); // $ExpectError
	snannsumkbn( x.length, undefined, 1, sum, count ); // $ExpectError
	snannsumkbn( x.length, [ '1' ], 1, sum, count ); // $ExpectError
	snannsumkbn( x.length, {}, 1, sum, count ); // $ExpectError
	snannsumkbn( x.length, ( x: number ): number => x, 1, sum, count ); // $ExpectError
}

