// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = new Float32Array( 10 );
	const sum = new Float32Array( 1 );
	const count = new Int32Array( 1 );

	snannsumkbn(); // $ExpectError
	snannsumkbn( x.length ); // $ExpectError
	snannsumkbn( x.length, x ); // $ExpectError
	snannsumkbn( x.length, x, 1 ); // $ExpectError
	snannsumkbn( x.length, x, 1, sum ); // $ExpectError
	snannsumkbn( x.length, x, 1, sum, count, 10 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a Float32Array...
{
	const x = new Float32Array( 10 );
	const sum = new Float32Array( 1 );
	const count = new Int32Array( 1 );

	snannsumkbn.ndarray( x.length, x, 1, 0, sum, 0, count, 0 ); // $ExpectType Float32Array
}

