	const count = new Int32Array( 1 );

	snannsumkbn.ndarray(); // $ExpectError
	snannsumkbn.ndarray( x.length ); // $ExpectError
	snannsumkbn.ndarray( x.length, x ); // $ExpectError
	snannsumkbn.ndarray( x.length, x, 1 ); // $ExpectError
